package com.bitewise.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="business_id",nullable=false) private Business business; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="actor_user_id",nullable=false) private User actor; @Column(nullable=false) private String action; @Column(name="entity_type") private String entityType; @Column(name="entity_id") private UUID entityId; private String details; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public AuditLog(){} public AuditLog(Business b,User u,String a,String t,UUID id,String d){business=b;actor=u;action=a;entityType=t;entityId=id;details=d;} public UUID getId(){return id;} public Business getBusiness(){return business;} public User getActor(){return actor;} public String getAction(){return action;} public String getEntityType(){return entityType;} public UUID getEntityId(){return entityId;} public String getDetails(){return details;} public Instant getCreatedAt(){return createdAt;} }
